import os

from keyword_list import keyword_list, infer_token_type

header = """/// WARNING: This code was generated by python/generate_keyword_map.py
///
/// DO NOT EDIT THIS CODE!!!
///
/// Instead, make changes to python/generate_keyword_map.py and python/keyword_list.py
/// and run the script to regenerate this code like this:
///
/// cd python
/// python3 generate_keyword_map.py
///

use std::collections::HashMap;
use crate::scanner::TokenType;

pub fn get_keyword_map() -> HashMap<String, TokenType> {
    return HashMap::from([
"""

footer = """    ])
}
"""

def workflow():
    output_path = os.path.join("..", "src", "scanner", "keyword_map.rs")

    map_data = ""
    for keyword in keyword_list:
        token_type = infer_token_type(keyword)
        map_data+=(f'        (String::from("{keyword}"), TokenType::{token_type}),\n')
    
    prog = header + map_data + footer

    with open(output_path, "w") as f:
        f.write(prog)
    

if __name__ == "__main__":
    workflow()